	private static final int SOURCE_SHIFT = 48;
	private static final long LOCAL_MASK = (1L << SOURCE_SHIFT) - 1;

	/**
	 * Runs up to this many edges are decoded once per handle into flat buffers; kernels then read plain arrays
	 * instead of paying a codec run-view resolution per access. Larger (supernode-class) runs keep the codec's
	 * once-per-batch copy path.
	 */
